python3 << 'PYSCRIPT'
import json

with open('/app/output/chart_data.json', 'r') as f:
    data = json.load(f)

chart_data_json = json.dumps(data)

# Build annual performance table rows
annual_rows = ""
for a in data['annual']:
    color = '#16a34a' if a['return'] >= 0 else '#dc2626'
    sign = '+' if a['return'] >= 0 else ''
    annual_rows += f"""<tr>
        <td>{a['year']}</td>
        <td style="color:{color};font-weight:600">{sign}{a['return']:.2f}%</td>
        <td>${a['high']:.2f}</td>
        <td>${a['low']:.2f}</td>
        <td>{a['avgVol']:,}</td>
    </tr>\n"""

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
<style>
  :root {{
    --bg: #ffffff;
    --surface: #f8f9fa;
    --border: #e2e8f0;
    --text: #1a202c;
    --text-muted: #64748b;
    --accent: #1e3a5f;
    --accent-light: #2563eb;
    --green: #16a34a;
    --red: #dc2626;
    --orange: #d97706;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: var(--text);
    background: var(--bg);
    line-height: 1.65;
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 24px;
  }}
  h1 {{
    font-size: 1.85rem;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 4px;
    letter-spacing: -0.02em;
  }}
  .subtitle {{
    font-size: 0.95rem;
    color: var(--text-muted);
    margin-bottom: 32px;
    border-bottom: 2px solid var(--accent);
    padding-bottom: 16px;
  }}
  h2 {{
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--accent);
    margin: 40px 0 16px 0;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border);
  }}
  h3 {{
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--text);
    margin: 24px 0 8px 0;
  }}
  p {{ margin-bottom: 14px; color: #374151; font-size: 0.935rem; }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin: 24px 0 32px 0;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
    text-align: center;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    margin-bottom: 6px;
    font-weight: 600;
  }}
  .kpi-card .kpi-value {{
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--accent);
  }}
  .kpi-card .kpi-sub {{
    font-size: 0.78rem;
    color: var(--text-muted);
    margin-top: 4px;
  }}
  .chart-container {{
    position: relative;
    margin: 20px 0 32px 0;
    padding: 16px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
  }}
  .chart-container canvas {{
    max-height: 400px;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.875rem;
  }}
  th {{
    background: var(--accent);
    color: white;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
  }}
  td {{
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
  }}
  tr:hover td {{ background: #f1f5f9; }}
  .phase-table td:first-child {{ font-weight: 600; white-space: nowrap; }}
  .callout {{
    background: #eff6ff;
    border-left: 4px solid var(--accent-light);
    padding: 14px 18px;
    margin: 16px 0;
    border-radius: 0 6px 6px 0;
    font-size: 0.9rem;
  }}
  .callout strong {{ color: var(--accent); }}
  .takeaway-list {{
    list-style: none;
    padding: 0;
  }}
  .takeaway-list li {{
    padding: 10px 0 10px 24px;
    border-bottom: 1px solid var(--border);
    position: relative;
    font-size: 0.925rem;
  }}
  .takeaway-list li::before {{
    content: "\\25B6";
    position: absolute;
    left: 0;
    color: var(--accent-light);
    font-size: 0.65rem;
    top: 14px;
  }}
  .decade-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 16px;
    margin: 16px 0;
  }}
  .decade-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px;
  }}
  .decade-card h4 {{
    font-size: 1rem;
    color: var(--accent);
    margin-bottom: 8px;
  }}
  .decade-stat {{
    display: flex;
    justify-content: space-between;
    padding: 4px 0;
    font-size: 0.875rem;
  }}
  .decade-stat span:last-child {{ font-weight: 600; }}
  .footer {{
    margin-top: 48px;
    padding-top: 16px;
    border-top: 1px solid var(--border);
    font-size: 0.78rem;
    color: var(--text-muted);
    text-align: center;
  }}
  @media (max-width: 768px) {{
    body {{ padding: 20px 12px; }}
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    h1 {{ font-size: 1.4rem; }}
  }}
</style>
</head>
<body>

<h1>Nike Inc. (NKE) Historical Stock Performance Analysis</h1>
<p class="subtitle">January 2000 – January 2026 &nbsp;|&nbsp; 6,559 Trading Days &nbsp;|&nbsp; 26 Years of Market Data</p>

<!-- ============ EXECUTIVE SUMMARY ============ -->
<h2>1. Executive Summary</h2>

<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Cumulative Return</div>
    <div class="kpi-value" style="color:var(--green)">+1,282%</div>
    <div class="kpi-sub">$4.47 &rarr; $61.81 (adj. close)</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">CAGR</div>
    <div class="kpi-value">10.60%</div>
    <div class="kpi-sub">Annualized over 26.1 years</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Maximum Drawdown</div>
    <div class="kpi-value" style="color:var(--red)">&minus;68.5%</div>
    <div class="kpi-sub">Nov 2021 peak &rarr; Apr 2025 trough</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Annualized Volatility</div>
    <div class="kpi-value">31.2%</div>
    <div class="kpi-sub">Daily returns &times; &radic;252</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Avg Daily Volume</div>
    <div class="kpi-value">10.7M</div>
    <div class="kpi-sub">Shares traded per day</div>
  </div>
</div>

<p>Over 26 years, Nike stock delivered a <strong>13.8x return</strong> on an adjusted basis, compounding at 10.6% annually. The journey, however, was far from smooth. NKE experienced two major drawdown episodes: a ~47% decline during the early-2000s period and a devastating 68.5% peak-to-trough decline from its November 2021 all-time high of $166.25 to its April 2025 trough. The stock's golden era was the 2010s, where it compounded at over 21% annually, driven by the direct-to-consumer transformation and global brand strength. However, the 2020s have been challenging, with the stock declining ~34% from the start of 2020 to January 2026 amid competitive pressures and shifting consumer preferences.</p>

<div class="callout">
  <strong>Key Insight:</strong> While Nike's long-term compounding has been exceptional, the stock's risk profile has intensified since 2021. The current drawdown is the deepest in the dataset, and annualized volatility has risen. Investors should weigh the proven brand franchise against the magnitude of the current structural correction.
</div>

<!-- ============ PRICE TREND ANALYSIS ============ -->
<h2>2. Long-Term Price Trend Analysis</h2>

<p>The chart below shows Nike's monthly closing prices from 2000 through January 2026, capturing the full arc of the stock's evolution from a split-adjusted ~$4.50 to its all-time high of $166.25 and subsequent decline.</p>

<div class="chart-container">
  <canvas id="priceChart"></canvas>
</div>

<h3>Structural Phases</h3>

<table class="phase-table">
<thead>
  <tr><th>Phase</th><th>Period</th><th>Price Range</th><th>Description</th></tr>
</thead>
<tbody>
  <tr>
    <td style="color:var(--red)">Early Downturn</td>
    <td>Jan 2000 – Feb 2000</td>
    <td>$4.47 &rarr; $2.47</td>
    <td>Sharp 45% decline in the first two months. Nike hit its all-time adjusted low of $2.47 on Feb 25, 2000 amid broad market weakness.</td>
  </tr>
  <tr>
    <td style="color:var(--green)">Recovery &amp; Growth I</td>
    <td>2000 – 2007</td>
    <td>$2.47 &rarr; $13.27</td>
    <td>Strong multi-year recovery driven by brand momentum and international expansion. The stock quintupled, though the 2002 bear market caused a 21% annual decline.</td>
  </tr>
  <tr>
    <td style="color:var(--red)">Financial Crisis</td>
    <td>2008</td>
    <td>$13.90 &rarr; $8.46</td>
    <td>The Global Financial Crisis drove an 18% annual decline, with the stock falling from highs near $14 to lows around $8.50.</td>
  </tr>
  <tr>
    <td style="color:var(--green)">Secular Bull Run</td>
    <td>2009 – 2021</td>
    <td>$7.66 &rarr; $166.25</td>
    <td>The defining era. A 13-year rally that took Nike from $7.66 to $166.25 — a 21.7x gain. Fueled by DTC transformation, digital acceleration, global athletic wear trends, and the COVID-era consumer shift to athleisure.</td>
  </tr>
  <tr>
    <td style="color:var(--red)">Structural Correction</td>
    <td>Nov 2021 – Present</td>
    <td>$166.25 &rarr; $61.81</td>
    <td>The deepest drawdown in the dataset at &minus;68.5%. Driven by competitive pressures (On, Hoka), inventory issues, China headwinds, and the unwinding of pandemic-era demand.</td>
  </tr>
</tbody>
</table>

<div class="callout">
  <strong>All-Time High:</strong> $166.25 on November 5, 2021 &nbsp;&nbsp;|&nbsp;&nbsp; <strong>All-Time Low:</strong> $2.47 on February 25, 2000 (split-adjusted)
</div>

<h3>Drawdown History</h3>
<p>The drawdown chart illustrates the percentage decline from the most recent peak at each point in time. The current drawdown cycle, beginning in late 2021, is both the deepest and most prolonged in the 26-year history.</p>

<div class="chart-container">
  <canvas id="drawdownChart"></canvas>
</div>

<!-- ============ VOLATILITY ANALYSIS ============ -->
<h2>3. Volatility and Risk Assessment</h2>

<p>Nike's annualized volatility across the full period stands at 31.2%, which is elevated relative to the broader market (S&amp;P 500 typically ~15–20%). This reflects the stock's beta characteristics as a consumer-discretionary name with earnings sensitivity to macro cycles.</p>

<div class="chart-container">
  <canvas id="volChart"></canvas>
</div>

<h3>Volatility Regime Observations</h3>
<table>
<thead>
  <tr><th>Period</th><th>Approx. Rolling 30-Day Vol</th><th>Context</th></tr>
</thead>
<tbody>
  <tr><td>Early 2000</td><td>~72%</td><td>Extreme volatility during the initial adjusted-price collapse</td></tr>
  <tr><td>2003–2006</td><td>12–18%</td><td>Low-volatility growth period; steady appreciation</td></tr>
  <tr><td>2008–2009</td><td>30–45%</td><td>Financial crisis elevated risk across all equities</td></tr>
  <tr><td>2010–2019</td><td>12–25%</td><td>The "goldilocks" era — strong returns with moderate volatility</td></tr>
  <tr><td>2020 (Mar)</td><td>~80%+</td><td>COVID crash produced extreme short-term volatility</td></tr>
  <tr><td>2022–2026</td><td>20–55%</td><td>Elevated and persistent volatility during the structural correction</td></tr>
</tbody>
</table>

<h3>Daily Price Range (% of Close)</h3>
<p>The average daily high-low spread as a percentage of the closing price provides another lens on intraday volatility. Periods of stress (2000, 2008, 2020, 2024–2025) show marked expansion in daily ranges.</p>

<div class="chart-container">
  <canvas id="rangeChart"></canvas>
</div>

<!-- ============ VOLUME ANALYSIS ============ -->
<h2>4. Trading Volume Patterns</h2>

<p>Trading volume reflects market conviction and liquidity. The chart below plots monthly average daily volume alongside the closing price, allowing correlation of volume spikes with price events.</p>

<div class="chart-container">
  <canvas id="volumeChart"></canvas>
</div>

<h3>Notable Volume Events</h3>
<table>
<thead>
  <tr><th>Date</th><th>Volume</th><th>Price Change</th><th>Context</th></tr>
</thead>
<tbody>
  <tr><td>Jun 28, 2024</td><td>130.0M</td><td style="color:var(--red)">&minus;20.0%</td><td>Largest single-day volume in the dataset. Major earnings disappointment or guidance cut triggered a historic selloff.</td></tr>
  <tr><td>Jun 27, 2025</td><td>117.5M</td><td style="color:var(--green)">+15.2%</td><td>Sharp reversal rally — likely earnings beat or strategic announcement after extended decline.</td></tr>
  <tr><td>Dec 19, 2025</td><td>108.7M</td><td style="color:var(--red)">&minus;10.5%</td><td>Another high-volume selloff near year-end, continuing the pattern of earnings-related volatility.</td></tr>
  <tr><td>Feb 27, 2001</td><td>97.8M</td><td style="color:var(--red)">&minus;19.8%</td><td>Early-era selloff with massive volume, likely tied to an earnings or guidance event.</td></tr>
  <tr><td>Jun 29, 2012</td><td>86.3M</td><td style="color:var(--red)">&minus;9.4%</td><td>Earnings-related volume spike during the mid-cycle growth era.</td></tr>
</tbody>
</table>

<div class="callout">
  <strong>Volume Trend:</strong> Average daily volume decreased from ~14M shares/day in 2006–2009 to ~7M in 2013–2021, reflecting reduced share count (buybacks) and a higher stock price. Volume has surged back to 16M+ in 2025–2026 as the stock trades at lower price levels with heightened uncertainty.
</div>

<!-- ============ ANNUAL PERFORMANCE ============ -->
<h2>5. Annual and Decade-Level Performance Breakdown</h2>

<h3>Year-Over-Year Returns</h3>
<div class="chart-container">
  <canvas id="annualChart"></canvas>
</div>

<table>
<thead>
  <tr><th>Year</th><th>Annual Return</th><th>High</th><th>Low</th><th>Avg Daily Vol</th></tr>
</thead>
<tbody>
  {annual_rows}
</tbody>
</table>

<h3>Decade-Level Compounding</h3>
<div class="decade-grid">
  <div class="decade-card">
    <h4>2000s (2000–2009)</h4>
    <div class="decade-stat"><span>Cumulative Return</span><span style="color:var(--green)">+200.0%</span></div>
    <div class="decade-stat"><span>CAGR</span><span>11.6%</span></div>
    <div class="decade-stat"><span>Key Events</span><span>Dot-com bust, GFC</span></div>
    <p style="font-size:0.83rem;margin-top:8px;color:var(--text-muted)">Despite two major market crises, Nike tripled in value over the decade, demonstrating the resilience of its brand franchise.</p>
  </div>
  <div class="decade-card">
    <h4>2010s (2010–2019)</h4>
    <div class="decade-stat"><span>Cumulative Return</span><span style="color:var(--green)">+604.4%</span></div>
    <div class="decade-stat"><span>CAGR</span><span>21.6%</span></div>
    <div class="decade-stat"><span>Key Events</span><span>DTC pivot, global growth</span></div>
    <p style="font-size:0.83rem;margin-top:8px;color:var(--text-muted)">Nike's golden decade. The direct-to-consumer transformation, digital innovation, and global athleisure trends produced extraordinary compounding with only one negative year (2016, &minus;16.4%).</p>
  </div>
  <div class="decade-card">
    <h4>2020s (2020–Jan 2026)</h4>
    <div class="decade-stat"><span>Cumulative Return</span><span style="color:var(--red)">&minus;34.4%</span></div>
    <div class="decade-stat"><span>CAGR</span><span style="color:var(--red)">&minus;6.7%</span></div>
    <div class="decade-stat"><span>Key Events</span><span>COVID, ATH, correction</span></div>
    <p style="font-size:0.83rem;margin-top:8px;color:var(--text-muted)">A tale of two halves: the COVID recovery drove the stock to its all-time high in Nov 2021, but the subsequent 68.5% drawdown has erased the decade's gains and then some. Three consecutive negative years (2022–2024) have been the worst stretch in Nike's history.</p>
  </div>
</div>

<!-- ============ KEY TAKEAWAYS ============ -->
<h2>6. Key Takeaways and Investment Implications</h2>

<ul class="takeaway-list">
  <li><strong>Proven Long-Term Compounder:</strong> A 10.6% CAGR over 26 years with a 13.8x total return demonstrates that Nike has been an exceptional long-term investment. Investors who held through the volatility were well-rewarded.</li>
  <li><strong>Severe Current Drawdown:</strong> The &minus;68.5% decline from the Nov 2021 high is the largest in the dataset, exceeding both the 2000 collapse and the 2008 financial crisis in magnitude. This suggests structural, not cyclical, headwinds — including competitive disruption from newer brands and a potentially over-extended DTC strategy.</li>
  <li><strong>Volatility Has Increased:</strong> Rolling volatility in 2024–2025 has been consistently above 30%, compared to the 12–18% range during Nike's strongest growth years. Higher volatility with negative returns is the worst combination for long-term compounding.</li>
